def knapsack(weights, values, capacity):
    # Initialize the dp table with 0 for all indices
    dp = [0] * (len(weights) + 1)

    # Loop through the items
    for i in range(1, len(weights) + 1):
        # Loop through the available weights
        for j in range(capacity + 1):
            # If the current weight is less than or equal to the available weight,
            # take the maximum of the value of the current item and the value of the previous item
            if weights[i - 1] <= j:
                dp[i][j] = max(values[i - 1] + dp[i - 1][j - weights[i - 1]], dp[i - 1][j])
            # Otherwise, take the value of the previous item
            else:
                dp[i][j] = dp[i - 1][j]

    # Return the maximum value of the last row
    return max(dp[-1])
```
