def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")
    parts = s.split()
    seconds = 0
    for part in parts:
        if part[-1] == "d":
            seconds += int(part[:-1]) * 24 * 60 * 60
        elif part[-1] == "h":
            seconds += int(part[:-1]) * 60 * 60
        elif part[-1] == "m":
            seconds += int(part[:-1]) * 60
        elif part[-1] == "s":
            seconds += int(part[:-1])
        else:
            raise ValueError("Invalid unit")
    return seconds
```
