def lru_misses(capacity: int, requests: list[int]) -> int:
    misses = 0
    cache = {}
    for key in requests:
        if key in cache:
            # Hit, move key to the end of the cache
            cache[key] = cache.pop(key)
        else:
            # Miss, insert new key and evict the least recently used key if necessary
            cache[key] = None
            if len(cache) > capacity:
                cache.popitem(last=False)
            misses += 1
    return misses
```
