def paths_with_obstacles(grid: list[list[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    dp = [[0] * (cols + 1) for _ in range(rows + 1)]
    dp[0][0] = 1
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            if grid[i - 1][j - 1] == 1:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    return dp[rows][cols]
```
