def min_window(s: str, t: str) -> str:
    # Check if t is empty
    if not t:
        return ''

    # Initialize a dictionary to count the frequency of each character in t
    t_count = {}
    for c in t:
        t_count[c] = t_count.get(c, 0) + 1

    # Initialize a window of size len(t)
    window = s[:len(t)]

    # Iterate over the characters in the window
    for i, c in enumerate(window):
        # If the character is in t, decrease its count
        if c in t_count:
            t_count[c] -= 1
            # If the count reaches 0, remove the character from t_count
            if t_count[c] == 0:
                del t_count[c]
        # If t_count is empty, all characters have been found
        if not t_count:
            return window[i:]

    # If we reach the end of the window, move the window by 1 character
    window = window[1:]

    # Repeat the process until t_count is empty
    for c in s[len(t):]:
        # If the character is in t, decrease its count
        if c in t_count:
            t_count[c] -= 1
            # If the count reaches 0, remove the character from t_count
            if t_count[c] == 0:
                del t_count[c]
        # If t_count is empty, all characters have been found
        if not t_count:
            return window[i:]

    # If we reach the end of the string and t_count is not empty, there is no substring that meets the requirements
    return ''

