def evaluate(expr: str) -> int:
    # Convert the expression to a postfix notation
    postfix = []
    for token in expr.split():
        if token.isdigit():
            postfix.append(int(token))
        elif token in '+-*/':
            postfix.append(token)
        elif token == '(':
            pass
        elif token == ')':
            pass
        else:
            raise ValueError(f"Invalid token: {token}")

    # Evaluate the postfix expression
    stack = []
    for token in postfix:
        if token.isdigit():
            stack.append(token)
        elif token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a // b)
        else:
            raise ValueError(f"Invalid token: {token}")

    return stack.pop()
```
