def lru_misses(capacity: int, requests: list[int]) -> int:
    hits = 0
    misses = 0
    cache = {}

    for key in requests:
        if key in cache:
            hits += 1
            cache[key] = None
        else:
            misses += 1
            cache[key] = None

            # Evict the least recently used key if the cache is over capacity
            if len(cache) > capacity:
                evicted_key = min(cache, key=lambda k: cache[k])
                del cache[evicted_key]

    return misses

