def knapsack(weights: list[int], values: list[int], capacity: int) -> int:
    # Initialize the dp table with 0 for all indices
    dp = [0] * (capacity + 1)

    # Iterate over the items
    for i, weight in enumerate(weights):
        # Iterate over the capacities
        for j in range(capacity, -1, -1):
            # Check if the current capacity is less than or equal to the current weight
            if j < weight:
                # If the weight is greater than the current capacity, set the value to 0
                dp[j] = 0
            else:
                # If the weight is less than or equal to the current capacity, set the value to the maximum of the current value and the value obtained by taking the current item
                dp[j] = max(dp[j], dp[j - weight] + values[i])

    # Return the maximum value obtained by taking any subset of items
    return max(dp)

