def regex_match(s: str, p: str) -> bool:
    if len(p) == 0:
        return len(s) == 0

    if len(s) == 0:
        return len(p) == 0

    if p[0] != '*' and p[0] != '.':
        if len(s) < 1 or p[0] != s[0]:
            return False
        return regex_match(s[1:], p[1:])

    if p[0] == '.':
        return regex_match(s[1:], p[1:])

    if p[0] == '*':
        return regex_match(s, p[1:]) or regex_match(s[1:], p)

