def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    parts = s.split()
    total_seconds = 0

    for part in parts:
        unit = part[-1]
        value = int(part[:-1])

        if unit == "d":
            total_seconds += value * 24 * 60 * 60
        elif unit == "h":
            total_seconds += value * 60 * 60
        elif unit == "m":
            total_seconds += value * 60
        elif unit == "s":
            total_seconds += value
        else:
            raise ValueError(f"Invalid unit: {unit}")

    return total_seconds
```
