def summarize_ranges(nums: list[int]) -> list[str]:
    ranges = []
    for i in range(len(nums)):
        if i + 1 < len(nums) and nums[i] + 1 == nums[i + 1]:
            continue
        if nums[i] == ranges[-1][-1] + 1:
            ranges[-1][-1] = nums[i]
        else:
