def evaluate(expr: str) -> int:
    # Split the expression into tokens
    tokens = expr.split()

    # Evaluate the expression using a stack
    stack = []
    for token in tokens:
        # If the token is an operator, pop the top two elements from the stack, apply the operation, and push the result back onto the stack
        if token in "+-*/":
            op2 = stack.pop()
            op1 = stack.pop()
            if token == "+":
                result = op1 + op2
            elif token == "-":
                result = op1 - op2
            elif token == "*":
                result = op1 * op2
            elif token == "/":
                result = op1 // op2
            stack.append(result)
        # If the token is a number, push it onto the stack
        else:
            stack.append(int(token))

    # The final result is the only element remaining in the stack
    return stack.pop()

